# RGB-derived: docs/fill_egg_holder/applied_values.json (rgb_derived_values).
# RGB geometry updates generated by --run-geometry-fitting.
# Evidence: docs/fill_egg_holder/geometry_fit.json
"""Executed perception-driven routines for fill_egg_holder.

Inputs are only: current RGB, camera calibration and proprioception
through the ``robo`` interface (SAM3 only as an optional cross-check).

Task: four eggs lie in a wicker basket; each must end in one of the four cups
of the egg carton, then the carton's lid must be closed and both arms returned
to their start pose.
"""
import math
import numpy as np
from PIL import Image, ImageDraw
# Directed self-play defaults: docs/self_play_estimates/reports/manifest.json
BASKET_RIM_PLANE_Z_M = 0.861932
BASKET_FAR_TO_CENTER_Y_M = 0.10538


# RGB geometry in metres. Carton offsets use the measured carton frame.
EGG_LENGTH_M = 0.056  # +/-0.003 across the four observed eggs.
EGG_DIAMETER_M = 0.041  # +/-0.002.
EGG_CENTER_Z = 0.803  # +/-0.003; observed resting centers range 0.803..0.804.
SUPPORT_Z = 0.765  # +/-0.0015 near the observed carton/basket.
CARTON_CUP_OFFSETS_M = ((-0.026, 0.028), (0.028, 0.029),
                        (-0.026, -0.027), (0.028, -0.026))  # +/-0.003 per axis.
CARTON_HINGE_Y_M = 0.060  # +/-0.004 relative to the carton center.
CARTON_HINGE_Z_M = 0.047  # +/-0.003 above the carton support.
CARTON_LID_LENGTH_M = 0.121  # +/-0.004.
BASKET_SEARCH_RADIUS_M = 0.109  # measured outer rim. docs/fill_egg_holder/geometry_fit.json
CARTON_FRONT_EDGE_TO_CENTER_M = 0.056



def cam(robo, name='cam_head'):
    m = robo.camera_meta(name)
    return np.asarray(m['intrinsic_matrix'], float), np.asarray(m['extrinsic_matrix'], float)


def pixel_ray(K, E, rc):
    """World origin and unit direction of the ray through pixel (row, col)."""
    r, c = float(rc[0]), float(rc[1])
    d = E[:3, :3] @ np.array([(c - K[0, 2]) / K[0, 0], -(r - K[1, 2]) / K[1, 1], -1.0])
    return E[:3, 3].copy(), d / np.linalg.norm(d)


def ray_at_z(K, E, rc, z):
    o, d = pixel_ray(K, E, rc)
    return o + (z - o[2]) / d[2] * d


def project(K, E, pts):
    """World points -> (row, col) pixels."""
    P = np.atleast_2d(np.asarray(pts, float))
    pc = (P - E[:3, 3]) @ E[:3, :3]
    col = K[0, 2] + K[0, 0] * pc[:, 0] / -pc[:, 2]
    row = K[1, 2] - K[1, 1] * pc[:, 1] / -pc[:, 2]
    return np.c_[row, col]


def rgb_of(robo, camera='cam_head'):
    return np.ascontiguousarray(np.asarray(robo.image(camera))[:, :, :3])


def _rx(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[1.0, 0.0, 0.0], [0.0, c, -s], [0.0, s, c]])


def _ry(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, 0.0, s], [0.0, 1.0, 0.0], [-s, 0.0, c]])


def _rz(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, -s, 0.0], [s, c, 0.0], [0.0, 0.0, 1.0]])


def orientation(pitch, yaw, roll=0.0):
    """Gripper rotation for (pitch, yaw, roll) in degrees: Rz(90 + yaw) Ry(pitch) Rx(roll). Column 0 points along the fingers."""
    return _rz(math.radians(90.0 + yaw)) @ _ry(math.radians(pitch)) @ _rx(math.radians(roll))


def wrap180(d):
    return (d + 90.0) % 180.0 - 90.0


def carton_pose(robo, camera='cam_head'):
    """Carton centre from the head view: the white body's front-bottom edge on the table and its side extents.

    The carton is assumed square to the table with the lid on the far side, so
    only its position is measured. White pixels are searched inside the
    projection of a fixed search region on the table; the lowest white
    pixel of each column is the front-bottom edge (on the table plane), and the
    lowest pixels' left and right ends are the front corners.
    """
    import cv2
    K, E = cam(robo, camera)
    rgb = rgb_of(robo, camera)
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    white = ((hsv[:, :, 1] < 40) & (hsv[:, :, 2] > 150)).astype(np.uint8)
    corners = [[x, y, z] for x in (-0.13, 0.13) for y in (-0.31, 0.03) for z in (SUPPORT_Z, SUPPORT_Z + 0.18)]
    px = project(K, E, corners)
    r0, r1 = int(max(0, px[:, 0].min())), int(min(rgb.shape[0] - 1, px[:, 0].max()))
    c0, c1 = int(max(0, px[:, 1].min())), int(min(rgb.shape[1] - 1, px[:, 1].max()))
    window = np.zeros_like(white)
    window[r0:r1 + 1, c0:c1 + 1] = white[r0:r1 + 1, c0:c1 + 1]
    window = cv2.morphologyEx(window, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    n, labels, stats, _ = cv2.connectedComponentsWithStats(window)
    if n < 2:
        return dict(ok=False, reason='no white carton in the head view')
    k = 1 + int(np.argmax(stats[1:, cv2.CC_STAT_AREA]))
    if stats[k, cv2.CC_STAT_AREA] < 1500:
        return dict(ok=False, reason='white region too small for the carton', area=int(stats[k, cv2.CC_STAT_AREA]))
    blob = labels == k
    cols = np.nonzero(blob.any(axis=0))[0]
    bottom = np.array([[np.nonzero(blob[:, c])[0].max(), c] for c in cols])
    low = bottom[:, 0].max()
    edge = bottom[bottom[:, 0] >= low - 6]
    if len(edge) < 20:
        return dict(ok=False, reason='front edge of the carton not found', columns=len(edge))
    pts = np.array([ray_at_z(K, E, rc, SUPPORT_Z) for rc in edge])
    y_front = float(np.median(pts[:, 1])) - 0.007
    left = ray_at_z(K, E, (edge[edge[:, 1].argmin()][0], edge[:, 1].min()), SUPPORT_Z)
    right = ray_at_z(K, E, (edge[edge[:, 1].argmax()][0], edge[:, 1].max()), SUPPORT_Z)
    width = float(right[0] - left[0])
    centre = np.array([(left[0] + right[0]) / 2.0, y_front + CARTON_FRONT_EDGE_TO_CENTER_M, SUPPORT_Z])
    ok = bool(0.105 <= width <= 0.140 and -0.07 <= centre[0] <= 0.07 and -0.26 <= centre[1] <= -0.07)
    cups = [centre + np.array([dx, dy, 0.0]) for dx, dy in CARTON_CUP_OFFSETS_M]
    top_row = project(K, E, centre + np.array([0.0, CARTON_HINGE_Y_M + 0.02, CARTON_HINGE_Z_M + CARTON_LID_LENGTH_M - 0.02]))[0, 0]
    rows = np.nonzero(blob.any(axis=1))[0]
    lid_open = bool(rows.min() <= top_row + 6)
    flat_row = project(K, E, centre + np.array([0.0, CARTON_HINGE_Y_M, CARTON_HINGE_Z_M + 0.04]))[0, 0]
    lid = 'open' if lid_open else ('closed' if rows.min() >= flat_row - 7 else 'ajar')
    return dict(ok=ok, centre=centre, cups=cups, width=width, y_front=y_front, lid_open=lid_open, lid=lid, blob=blob, area=int(blob.sum()),
                reason=None if ok else 'carton measurement outside its expected size or place')


def cup_states(robo, H, camera='cam_head'):
    """Which cups hold an egg, from colour: an egg is cream (saturated), an empty cup is white.

    Each cup is sampled on a small disc around the projection of a seated
    egg's top: ``fraction`` of egg-coloured pixels, ``occupied`` when at least
    half. For an occupied cup the egg-coloured blob under the disc is measured:
    an egg standing in its cup shows as a round blob about 21 px across
    (275-400 px); an egg lying across the cup is wider and larger (``standing``
    False). Two touching eggs make one large blob: ``standing`` None.
    """
    import cv2
    K, E = cam(robo, camera)
    hsv = cv2.cvtColor(rgb_of(robo, camera), cv2.COLOR_RGB2HSV).astype(int)
    eggish = (hsv[:, :, 1] >= 30) & (hsv[:, :, 2] >= 150) & (hsv[:, :, 0] >= 8) & (hsv[:, :, 0] <= 30)
    n, labels, stats, _ = cv2.connectedComponentsWithStats(eggish.astype(np.uint8))
    out = []
    for cup in H['cups']:
        r, c = project(K, E, np.asarray(cup) + [0.0, 0.0, 0.030 + 0.022])[0]
        rr, cc = np.ogrid[:eggish.shape[0], :eggish.shape[1]]
        disc = (rr - r) ** 2 + (cc - c) ** 2 <= 4.5 ** 2
        frac = float(eggish[disc].mean()) if disc.any() else 0.0
        row = dict(fraction=round(frac, 2), occupied=bool(frac >= 0.5), pixel=(float(r), float(c)), standing=None)
        under = labels[disc]
        under = under[under > 0]
        if row['occupied'] and len(under):
            k = int(np.bincount(under).argmax())
            area, width = int(stats[k, cv2.CC_STAT_AREA]), int(stats[k, cv2.CC_STAT_WIDTH])
            row.update(blob_area=area, blob_width=width)
            if area <= 600:
                row['standing'] = bool(area <= 430 and width <= 25)
        out.append(row)
    return out


def egg_mask(rgb, egg_px=18.0):
    """Egg-coloured, smooth pixels. ``egg_px`` is the egg's expected short diameter in pixels.

    From the head camera (eggs about 18 px across) eggs are brighter and less
    saturated than the wicker. In a wrist close-up (60 px and more) the light
    wicker strands have almost the egg's colour, but they are thin and
    textured while an egg is one large smooth blob: the close-up mask is
    opened with a kernel a quarter of an egg wide.
    """
    import cv2
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    h, s, v = hsv[:, :, 0].astype(int), hsv[:, :, 1].astype(int), hsv[:, :, 2].astype(np.float32)
    close = egg_px >= 35.0
    if close:
        colour = (h >= 12) & (h <= 26) & (s >= 10) & (s <= 80) & (v >= 212)
        win, limit = 7, 8.0
    else:
        colour = (h >= 10) & (h <= 28) & (s >= 22) & (s <= 75) & (v >= 205)
        win, limit = 5, 9.0
    mean = cv2.blur(v, (win, win))
    var = cv2.blur(v * v, (win, win)) - mean * mean
    smooth = np.sqrt(np.maximum(var, 0.0)) < limit
    m = (colour & smooth).astype(np.uint8)
    k = max(3, int(round(egg_px / 4.0)) | 1) if close else 3
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (k, k))
    m = cv2.morphologyEx(m, cv2.MORPH_OPEN, kernel)
    if close:
        wide = ((h >= 10) & (h <= 27) & (s <= 118) & (v >= 180)).astype(np.uint8)
        wide = cv2.morphologyEx(wide, cv2.MORPH_OPEN, kernel)
        n, labels = cv2.connectedComponents(wide)
        keep = np.unique(labels[m > 0])
        grown = np.isin(labels, keep[keep > 0]).astype(np.uint8)
        m = cv2.morphologyEx(grown, cv2.MORPH_CLOSE, kernel)
        k2 = int(round(0.3 * egg_px)) | 1
        m = cv2.morphologyEx(m, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (k2, k2)))
    return m


def wicker_mask(rgb):
    import cv2
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    h, s, v = hsv[:, :, 0].astype(int), hsv[:, :, 1].astype(int), hsv[:, :, 2].astype(int)
    return ((h >= 12) & (h <= 30) & (s >= 45) & (v >= 150)).astype(np.uint8)


def split_touching(blob, a, b):
    """Split a blob of touching eggs into one mask per egg. ``a``/``b``: an egg's half length/half width in pixels.

    One seed per egg at the peaks of the distance transform (the middle of each egg is deeper inside the blob
    than any neck between two eggs). Then a few rounds of: every pixel goes to the egg whose ellipse (known
    size, current centre and direction) it lies deepest in; each egg's centre and direction are re-estimated
    from its pixels.
    """
    import cv2
    dt = cv2.distanceTransform(blob, cv2.DIST_L2, 5)
    reach = int(1.4 * b) | 1
    peaks = np.argwhere((dt >= cv2.dilate(dt, np.ones((reach, reach), np.uint8)) - 1e-6) & (dt > 0.7 * b))
    centres = []
    for p in sorted(peaks.tolist(), key=lambda p: -dt[p[0], p[1]]):
        if all(math.hypot(p[0] - c[0], p[1] - c[1]) > 1.4 * b for c in centres):
            centres.append(np.array(p, float))
    if len(centres) < 2:
        return None
    rr, cc = np.nonzero(blob)
    P = np.c_[rr, cc].astype(float)
    angle = [0.0] * len(centres)
    owner = None
    for it in range(8):
        D = []
        for c, t in zip(centres, angle):
            d = P - c
            if it == 0:
                D.append((d ** 2).sum(axis=1))
            else:
                u = d[:, 0] * math.sin(t) + d[:, 1] * math.cos(t)
                w = -d[:, 0] * math.cos(t) + d[:, 1] * math.sin(t)
                D.append((u / a) ** 2 + (w / b) ** 2)
        owner = np.argmin(np.array(D), axis=0)
        for j in range(len(centres)):
            Q = P[owner == j]
            if len(Q) < 20:
                continue
            centres[j] = Q.mean(axis=0)
            _, vec = np.linalg.eigh(np.cov((Q - centres[j]).T))
            angle[j] = math.atan2(vec[0, 1], vec[1, 1])
    parts = []
    for j in range(len(centres)):
        part = np.zeros_like(blob)
        sel = owner == j
        part[rr[sel], cc[sel]] = 1
        parts.append(part)
    return parts


def find_eggs(robo, camera='cam_head', region=None, z=EGG_CENTER_Z):
    """Eggs lying in the basket: centre on the egg-centre plane, long-axis heading, size.

    Blobs of egg-coloured smooth pixels are split when two eggs touch (distance
    transform peaks). Each egg's centre is its blob centroid's ray at the
    egg-centre height; its long axis is the blob's principal axis on that plane.
    ``region`` = (centre_xy, radius) limits the search to the basket.
    """
    import cv2
    K, E = cam(robo, camera)
    rgb = rgb_of(robo, camera)
    o = E[:3, 3]
    ref = np.asarray(region[0], float) if region is not None else ray_at_z(K, E, (K[1, 2], K[0, 2]), z)
    ref = np.array([ref[0], ref[1], z])
    egg_px = EGG_DIAMETER_M * K[0, 0] / float(np.linalg.norm(ref - o))
    m = egg_mask(rgb, egg_px)
    n, labels, stats, cents = cv2.connectedComponentsWithStats(m)
    eggs = []
    for i in range(1, n):
        area = stats[i, cv2.CC_STAT_AREA]
        r, c = cents[i][1], cents[i][0]
        p = ray_at_z(K, E, (r, c), z)
        dist = float(np.linalg.norm(p - o))
        scale = K[0, 0] / dist
        full = math.pi / 4.0 * EGG_LENGTH_M * EGG_DIAMETER_M * scale * scale
        if area < 0.25 * full:
            continue
        if region is not None and np.linalg.norm(p[:2] - np.asarray(region[0])[:2]) > region[1]:
            continue
        blob = (labels == i).astype(np.uint8)
        parts = [blob]
        if area > 1.45 * full:
            parts = split_touching(blob, EGG_LENGTH_M / 2.0 * scale, EGG_DIAMETER_M / 2.0 * scale) or parts
        if egg_px >= 35.0:
            trim = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (int(0.45 * egg_px) | 1, int(0.45 * egg_px) | 1))
            parts = [cv2.morphologyEx(part, cv2.MORPH_OPEN, trim) for part in parts]
        for part in parts:
            rr, cc = np.nonzero(part)
            if len(rr) < 0.25 * full:
                continue
            if egg_px >= 35.0:
                hull = cv2.convexHull(np.c_[cc, rr].astype(np.int32))
                solidity = len(rr) / max(1.0, cv2.contourArea(hull))
                if solidity < 0.86 or len(rr) > 1.5 * full or len(rr) < 0.45 * full:
                    continue
            sel = np.arange(0, len(rr), max(1, len(rr) // 500))
            pts = np.array([ray_at_z(K, E, (rr[k], cc[k]), z)[:2] for k in sel])
            mean = pts.mean(axis=0)
            w, vec = np.linalg.eigh(np.cov((pts - mean).T))
            long_dir = vec[:, 1]
            heading = math.degrees(math.atan2(long_dir[1], long_dir[0]))
            eggs.append(dict(centre=np.array([mean[0], mean[1], z]), heading_deg=wrap180(heading),
                             length=float(4.0 * math.sqrt(max(w[1], 0.0))), width=float(4.0 * math.sqrt(max(w[0], 0.0))),
                             pixels=int(len(rr)), pixel=(float(rr.mean()), float(cc.mean())), full_px=float(full)))
    return dict(ok=bool(eggs), eggs=eggs, count=len(eggs), mask=m, egg_px=float(egg_px))


def find_basket(robo, camera='cam_head'):
    """Basket centre from the wicker-coloured region of the head view (rim centre projected on the rim plane)."""
    import cv2
    K, E = cam(robo, camera)
    rgb = rgb_of(robo, camera)
    w = wicker_mask(rgb) | egg_mask(rgb, 18.0)
    w = cv2.morphologyEx(w, cv2.MORPH_CLOSE, np.ones((9, 9), np.uint8))
    w = cv2.morphologyEx(w, cv2.MORPH_OPEN, np.ones((5, 5), np.uint8))
    n, labels, stats, cents = cv2.connectedComponentsWithStats(w)
    best = None
    for i in range(1, n):
        area = stats[i, cv2.CC_STAT_AREA]
        if area < 2500:
            continue
        r, c = cents[i][1], cents[i][0]
        p = ray_at_z(K, E, (r, c), SUPPORT_Z + 0.05)
        if not (-0.50 <= p[0] <= 0.50 and -0.33 <= p[1] <= 0.02):
            continue
        if best is None or area > best[0]:
            best = (area, p, labels == i)
    if best is None:
        return dict(ok=False, reason='no wicker basket in the head view')
    blob = best[2]
    rows = np.nonzero(blob.any(axis=1))[0]
    widths = np.array([blob[r].sum() for r in rows])
    widest = int(np.median(rows[widths >= widths.max() - 2]))
    cols = np.nonzero(blob[widest])[0]
    # Directed self-play optical rim reference. docs/self_play_estimates/reports/manifest.json
    left = ray_at_z(K, E, (widest, cols.min()), BASKET_RIM_PLANE_Z_M)
    right = ray_at_z(K, E, (widest, cols.max()), BASKET_RIM_PLANE_Z_M)
    far = ray_at_z(K, E, (rows.min(), np.nonzero(blob[rows.min()])[0].mean()), BASKET_RIM_PLANE_Z_M)
    centre = np.array([(left[0] + right[0]) / 2.0, far[1] - BASKET_FAR_TO_CENTER_Y_M, SUPPORT_Z + 0.05])
    return dict(ok=True, centre=centre, area=int(best[0]), blob=blob, rim_diameter=float(right[0] - left[0]))




def used(robo):
    return int(robo.action_count())


def go(robo, arm, xyz, pitch=None, yaw=None, roll=None, path='line', gripper=0, label=''):
    """One move with a compact reply."""
    before = used(robo)
    m = robo.move_to([float(v) for v in xyz], arm=arm, gripper=gripper, pitch=pitch, yaw=yaw, roll=roll, path=path)
    rec = dict(label=label, arm=arm, reached=bool(m.reached), blocked=bool(getattr(m, 'blocked', False)),
               dist=float(getattr(m, 'dist_to_target_m', float('nan'))), note=getattr(m, 'note', None),
               ik_error=getattr(m, 'ik_error', None), actions=used(robo) - before, at=used(robo))
    return rec


def approach(robo, arm, xyz, opening=None, label='', **kw):
    """Move an empty hand to a pose, opened to ``opening`` on the way (None: closed).

    The opening is commanded before the move and kept during it, so the fingers, which trail the command by
    several actions, are fully there on arrival. Openings below 0.9 never let the arm take the half-turned pose.
    """
    if opening is None:
        return go(robo, arm, xyz, gripper=robo.CLOSE, label=label, **kw)
    o = open_hand(robo, arm, opening, calls=1)
    rec = go(robo, arm, xyz, gripper=robo.KEEP, label=label, **kw)
    return dict(rec, actions=rec['actions'] + o['actions'], opened=round(o['opening'], 3), hand_open=o['opened'])


def glide(robo, arm, xyz, step_m=0.015, label='', **kw):
    """Straight move in short steps, one action each: no swing, low acceleration."""
    start = np.asarray(robo.state().arm(arm).tcp_pos, float)
    goal = np.asarray(xyz, float)
    n = max(1, int(math.ceil(np.linalg.norm(goal - start) / step_m)))
    before = used(robo)
    rec = None
    for k in range(1, n + 1):
        rec = go(robo, arm, start + (goal - start) * k / n, path='line', label=label, **kw)
        if not rec['reached'] and rec.get('ik_error'):
            break
    return dict(rec, actions=used(robo) - before, steps=n)




def open_hand(robo, arm, opening, calls=2):
    """Command an opening ``calls`` times (two or more actions each) so the fingers have time to get there.

    One open command returns as soon as the READING stops changing, long before the fingers have moved; a move
    made right after it carries a hand that is still nearly closed. There is no measurement of the
    fingers while they open, so this waits by repeating the command.
    """
    spent = 0
    reading = None
    for _ in range(calls):
        g = robo.set_gripper(arm, robo.OPEN) if opening >= 0.999 else robo.set_gripper(arm, robo.OPEN, opening=opening)
        spent += int(g.steps_used)
        reading = float(g.opening)
    return dict(opening=reading, actions=spent, opened=bool(reading is not None and reading >= opening - 0.05))


def near_enough(rec, slack=0.04):
    """A look pose is usable when the arm got within a few centimetres of it: the camera's real pose is read from its calibration."""
    if rec['reached']:
        return True
    d = rec.get('dist')
    return bool(not rec.get('ik_error') and d is not None and d == d and d <= slack)




