def basket_look(robo, arm, centre_xy):
    """Every egg in the basket from the wrist camera looking straight down: centre and long-axis heading.

    The hand is closed and stays above the basket rim. If the basket is not in
    the middle of the view the hand is shifted once and the look repeated.
    """
    start = used(robo)
    name = 'cam_%s_wrist' % arm
    target = np.asarray(centre_xy, float)[:2]
    shift = np.zeros(2)
    rec = None
    found = dict(ok=False, eggs=[], count=0)
    for attempt in range(2):
        for z in (1.01, 0.975, 0.94):
            ahead = 0.0155 + (240.0 - 130.0) / 397.0 * (z + 0.077 - 0.80)
            at = target + shift - np.array([0.0, ahead])
            rec = go(robo, arm, [at[0], at[1], z], pitch=60.0, yaw=0.0, roll=0.0, path='auto', gripper=robo.CLOSE, label='basket-look')
            if rec['reached'] or not rec.get('ik_error'):
                break
        if not near_enough(rec):
            return dict(ok=False, reason='look pose over the basket not reached', reply=rec, actions=used(robo) - start, eggs=[], count=0)
        K, E = cam(robo, name)
        view = ray_at_z(K, E, (130.0, K[0, 2]), 0.80)[:2]
        found = find_eggs(robo, name, region=(target, BASKET_SEARCH_RADIUS_M + 0.02))
        if found['count']:
            off = np.mean([e['centre'][:2] for e in found['eggs']], axis=0) - view
        else:
            off = np.array([0.0, 0.06])
        if attempt == 0 and float(np.linalg.norm(off)) > 0.05:
            shift = np.clip(off, -0.12, 0.12)
            continue
        break
    return dict(ok=bool(found['count']), reason=None if found['count'] else 'no egg seen in the basket', eggs=found['eggs'], count=found['count'],
                reply=rec, camera=name, actions=used(robo) - start)


def eggs_overlay(robo, camera, eggs, chosen=None):
    """Evidence image: each measured egg's centre and long axis drawn on the camera image."""
    K, E = cam(robo, camera)
    im = Image.fromarray(rgb_of(robo, camera)).convert('RGB')
    dr = ImageDraw.Draw(im)
    for i, e in enumerate(eggs):
        c = np.asarray(e['centre'], float)
        h = math.radians(e['heading_deg'])
        a = c + 0.03 * np.array([math.cos(h), math.sin(h), 0.0])
        b = c - 0.03 * np.array([math.cos(h), math.sin(h), 0.0])
        (r0, c0), (r1, c1), (rc, cc) = project(K, E, [a, b, c])
        col = (255, 0, 0) if chosen is not None and i == chosen else (0, 200, 255)
        dr.line([(c0, r0), (c1, r1)], fill=col, width=2)
        dr.ellipse([cc - 3, rc - 3, cc + 3, rc + 3], outline=col, width=2)
    return im


def carton_overlay(robo, H, states=None, camera='cam_head'):
    """Evidence image: carton centre and the four cups (green = measured occupied, yellow = empty)."""
    K, E = cam(robo, camera)
    im = Image.fromarray(rgb_of(robo, camera)).convert('RGB')
    dr = ImageDraw.Draw(im)
    if H.get('centre') is not None:
        for i, cup in enumerate(H['cups']):
            r, c = project(K, E, np.asarray(cup) + [0.0, 0.0, 0.030 + 0.022])[0]
            col = (0, 255, 0) if states and states[i]['occupied'] else (255, 255, 0)
            dr.ellipse([c - 5, r - 5, c + 5, r + 5], outline=col, width=2)
            dr.text((c + 6, r - 6), str(i), fill=col)
        r, c = project(K, E, H['centre'])[0]
        dr.ellipse([c - 2, r - 2, c + 2, r + 2], outline=(255, 0, 255), width=2)
    return im.resize((im.width * 2, im.height * 2))


