def wall_side(egg, basket_xy):
    """How far from the basket centre the outer finger of a pinch across this egg's short axis would come down."""
    c = np.asarray(egg['centre'], float)[:2] - np.asarray(basket_xy, float)[:2]
    h = math.radians(egg['heading_deg'] + 90.0)
    n = np.array([math.cos(h), math.sin(h)])
    return float(max(np.linalg.norm(c + 0.033 * n), np.linalg.norm(c - 0.033 * n)))


def pick_order(eggs, basket_xy=None):
    """Eggs whose pinch clears the basket wall first; among those the most isolated (neighbours least in the fingers' way)."""
    def room(i):
        others = [np.linalg.norm(eggs[i]['centre'][:2] - e['centre'][:2]) for j, e in enumerate(eggs) if j != i]
        return min(others) if others else 1.0

    def key(i):
        blocked = basket_xy is not None and wall_side(eggs[i], basket_xy) > 0.095
        return (1 if blocked else 0, -room(i))
    return sorted(range(len(eggs)), key=key)


def nudge_in(robo, arm, egg, basket_xy):
    """Roll an egg that lies against the basket wall toward the middle of the basket.

    The closed fingers come down just outside the egg, above its widest part (the wall leans outward, so there is
    room up there), flat side toward the basket centre, and sweep inward. Nothing is grasped.
    """
    start = used(robo)
    out = []
    c = np.asarray(basket_xy, float)[:2]
    e = np.asarray(egg['centre'], float)[:2]
    r = float(np.linalg.norm(e - c))
    if r < 0.010:
        return dict(ok=False, reason='egg already in the middle', replies=out, actions=0)
    u = (e - c) / r
    yaw = wrap180(math.degrees(math.atan2(u[1], u[0])) + 90.0)
    kw = dict(pitch=88.0, yaw=yaw, roll=0.0, gripper=robo.CLOSE)
    high = 0.865 + 0.045
    r0 = min(r + 0.030, 0.086)
    z = 0.80 + 0.010 + 0.022
    r1 = 0.020 + 0.019
    out.append(go(robo, arm, [c[0] + r0 * u[0], c[1] + r0 * u[1], high], path='auto', label='above-wall-side', **kw))
    if not out[-1]['reached']:
        return dict(ok=False, reason='pose beside the egg not reached', replies=out, actions=used(robo) - start)
    out.append(go(robo, arm, [c[0] + r0 * u[0], c[1] + r0 * u[1], z], label='down-above-egg-side', **kw))
    out.append(go(robo, arm, [c[0] + r1 * u[0], c[1] + r1 * u[1], z], label='sweep-in', **kw))
    out.append(go(robo, arm, [c[0] + r1 * u[0], c[1] + r1 * u[1], high], label='up', **kw))
    return dict(ok=True, reason=None, replies=out, actions=used(robo) - start, from_centre=r)


