def pick_egg(robo, arm, egg, basket_xy=None):
    """Pinch a lying egg from above across its short axis, at its middle, and lift it clear of the basket.

    Near the basket wall the hand aims a few millimetres toward the basket centre so that its outer finger comes
    down on the floor, not on the sloping wall; a descent that is still stopped is tried once more further in.
    After closing, the pinch reading tells where the egg sits in the hand: an off-centre egg is first carried
    3 cm toward the basket centre when it lay near the wall (room for the fingers), then the hand opens, shifts
    by the measured offset and closes again.
    """
    start = used(robo)
    out = []

    def done(ok, reason=None, **kw):
        return dict(ok=ok, reason=reason, replies=out, actions=used(robo) - start, **kw)

    x, y = float(egg['centre'][0]), float(egg['centre'][1])
    yaw = wrap180(egg['heading_deg'] - 90.0)
    kw = dict(pitch=88.0, yaw=yaw, roll=0.0)
    side = orientation(88.0, yaw)[:, 1]
    inward = np.zeros(2)
    r = 0.0
    if basket_xy is not None:
        c = np.asarray(basket_xy, float)[:2]
        r = float(np.linalg.norm(np.array([x, y]) - c))
        if r > 1e-6:
            inward = (c - np.array([x, y])) / r
        over = wall_side(egg, basket_xy) - 0.079
        if over > 0.0:
            bias = min(0.008, over + 0.002)
            x, y = x + bias * float(inward[0]), y + bias * float(inward[1])
    out.append(approach(robo, arm, [x, y, 0.915 - 0.03], opening=0.66, path='auto', label='above-egg', **kw))
    if not out[-1]['reached']:
        return done(False, 'pose above the egg not reached')
    if not out[-1].get('hand_open'):
        return done(False, 'hand did not open above the egg')
    out.append(go(robo, arm, [x, y, EGG_CENTER_Z], label='descend', **kw))
    low = float(robo.state().arm(arm).tcp_pos[2])
    if low > EGG_CENTER_Z + 0.006 and r > 0.02:
        x, y = x + 0.008 * float(inward[0]), y + 0.008 * float(inward[1])
        out.append(go(robo, arm, [x, y, low + 0.015], label='shift-inward', **kw))
        out.append(go(robo, arm, [x, y, EGG_CENTER_Z], label='descend', **kw))
        low = float(robo.state().arm(arm).tcp_pos[2])
    if low > EGG_CENTER_Z + 0.02:
        out.append(go(robo, arm, [x, y, 0.915 - 0.03], label='back-up', **kw))
        return done(False, 'descent to the egg blocked %.0f mm above it' % ((low - EGG_CENTER_Z) * 1000))
    near_wall = bool(basket_xy is not None and r > 0.030 and wall_side(egg, basket_xy) > 0.07)
    g = None
    w = 0.0
    shifted_from = None
    for attempt in range(4):
        c = open_hand(robo, arm, 0.58, calls=2)
        g = robo.set_gripper(arm, robo.CLOSE)
        w = float(g.width_m or 0.0)
        out.append(dict(label='close', holding=bool(g.holding), width=g.width_m, actions=g.steps_used + c['actions']))
        if not g.holding or not ((0.028, 0.062)[0] <= w <= (0.028, 0.062)[1]):
            break
        if shifted_from is not None and abs(w - shifted_from) < 0.0015 and abs(w - 0.04) > 0.008:
            out.append(dict(label='centring-ineffective', width=round(w, 4), before=round(shifted_from, 4)))
            break
        shifted_from = None
        even = abs(w - 0.04) <= 0.006
        if near_wall:
            near_wall = False
            if not even:
                x, y = x + 0.030 * float(inward[0]), y + 0.030 * float(inward[1])
                out.append(go(robo, arm, [x, y, EGG_CENTER_Z + 0.02], gripper=robo.CLOSE, label='drag-inward', **kw))
                out.append(go(robo, arm, [x, y, EGG_CENTER_Z], gripper=robo.CLOSE, label='set-down', **kw))
                o = open_hand(robo, arm, 0.66, calls=2)
                out.append(dict(label='let-go-inside', opened=round(o['opening'], 3), actions=o['actions']))
                continue
        if even or attempt == 3:
            break
        off = max(-0.012, min(0.012, w / 2.0 - 0.04 / 2.0))
        shifted_from = w
        o = open_hand(robo, arm, 0.66, calls=2)
        x, y = x + off * float(side[0]), y + off * float(side[1])
        out.append(dict(go(robo, arm, [x, y, EGG_CENTER_Z], label='centre-on-egg', **kw), shift_mm=round(off * 1000.0, 1), actions_open=o['actions']))
    if not g.holding or not ((0.028, 0.062)[0] <= w <= (0.028, 0.062)[1]) or abs(w - 0.04) > 0.008:
        o = open_hand(robo, arm, 0.72, calls=2)
        out.append(dict(label='let-go', opened=round(o['opening'], 3), actions=o['actions']))
        out.append(go(robo, arm, [x, y, 0.915 - 0.03], label='back-up', **kw))
        return done(False, 'no evenly held egg between the pads (width %s)' % (None if g.width_m is None else round(g.width_m, 3)), width=g.width_m)
    out.append(go(robo, arm, [x, y, 0.915], gripper=robo.CLOSE, label='lift', **kw))
    st = robo.state().arm(arm)
    settled = 0.0023 + 0.1091 * float(st.gripper)
    held = bool((0.0355, 0.047)[0] <= settled <= (0.0355, 0.047)[1])
    out.append(dict(label='held-after-lift', held=held, gripper=round(float(st.gripper), 3), width=round(settled, 4)))
    if not held:
        if st.gripper > 0.05:
            out.append(go(robo, arm, [x, y, EGG_CENTER_Z + 0.004], gripper=robo.CLOSE, label='set-down', **kw))
            o = open_hand(robo, arm, 0.72, calls=2)
            out.append(dict(label='let-go', opened=round(o['opening'], 3), actions=o['actions']))
            out.append(go(robo, arm, [x, y, 0.915 - 0.03], label='back-up', **kw))
        return done(False, 'egg not held across its middle (settled width %.3f)' % settled, width=settled)
    return done(True, width=g.width_m, yaw=yaw)


def wrist_point(cup, p, yaw, arm):
    """Where the wrist block is (plan view) with the egg over this cup."""
    fwd = orientation(p, yaw)[:, 0]
    flat = fwd[:2] / np.linalg.norm(fwd[:2])
    left = np.array([-flat[1], flat[0]])
    own = left if arm == 'left' else -left
    return np.asarray(cup, float)[:2] - 0.16 * flat + 0.07 * own




def pose_fits(cup, p, yaw, arm, basket_xy):
    """A flat hand pose whose wrist point is clear of the basket rim and of the camera stand."""
    w = wrist_point(cup, p, yaw, arm)
    if abs(w[0]) < 0.14 and w[1] < -0.385:
        return False
    return basket_xy is None or float(np.linalg.norm(w - np.asarray(basket_xy, float)[:2])) >= 0.185


def place_egg(robo, arm, H, index, basket_xy=None):
    """Carry the held egg over a cup, lower it into the cup mouth, let it go, withdraw straight up."""
    start = used(robo)
    out = []

    def done(ok, reason=None, **kw):
        return dict(ok=ok, reason=reason, replies=out, actions=used(robo) - start, **kw)

    cup = np.asarray(H['cups'][index], float)
    side = -1.0 if arm == 'left' else 1.0
    poses = [(p, side * turn) for p, turn in ((8.0, 0.0), (8.0, 30.0), (8.0, 55.0), (8.0, -35.0), (35.0, 0.0))]
    clear = [q for q in poses if q[0] < 30.0 and pose_fits(cup, q[0], q[1], arm, basket_xy)]
    steep = [q for q in poses if q[0] >= 30.0]
    poses = clear + steep + [q for q in poses if q not in clear and q not in steep]
    best = None
    lowest = None
    for p, yaw in poses:
        fwd = orientation(p, yaw)[:, 0]
        flat = fwd[:2] / np.linalg.norm(fwd[:2])
        tx, ty = cup[0] - 0.004 * fwd[0], cup[1] - 0.004 * fwd[1]
        if p >= 30.0:
            lean = 0.85 * EGG_LENGTH_M / 2.0 * math.sin(math.radians(p))
            tx, ty = tx + lean * flat[0], ty + lean * flat[1]
        tz = cup[2] + 0.074 + (0.008 if p >= 30.0 else 0.0)
        kw = dict(pitch=p, yaw=yaw, roll=0.0, gripper=robo.CLOSE)
        back = 0.04 if index < 2 else 0.0
        pre = [tx - back * flat[0], ty - back * flat[1], 0.915]
        rec = go(robo, arm, pre, path='auto', label='over-cup', **kw)
        out.append(dict(rec, pose=(p, yaw)))
        if not rec['reached']:
            continue
        if float(robo.state().arm(arm).gripper) <= 0.2:
            return done(False, 'egg lost on the way to the carton', holding=False)
        if back:
            out.append(dict(go(robo, arm, [tx, ty, 0.915], label='centre-over-cup', **kw), pose=(p, yaw)))
        rec = go(robo, arm, [tx, ty, tz], label='lower-into-cup', **kw)
        out.append(dict(rec, pose=(p, yaw)))
        tcp = np.asarray(robo.state().arm(arm).tcp_pos, float)
        height = float(tcp[2] - cup[2])
        off = float(np.linalg.norm(tcp[:2] - np.array([tx, ty])))
        if off <= 0.008 and (lowest is None or height < lowest[0]):
            lowest = (height, p, yaw, tcp, pre, [tx, ty, tz])
        if off <= 0.008 and height <= 0.082 + (0.008 if p >= 30.0 else 0.0):
            best = (p, yaw, tcp)
            break
        out.append(go(robo, arm, pre, label='back-up', **kw))
    if best is None and lowest is not None and lowest[0] <= 0.095 + 0.015:
        height, p, yaw, tcp, pre, target = lowest
        kw = dict(pitch=p, yaw=yaw, roll=0.0, gripper=robo.CLOSE)
        out.append(dict(go(robo, arm, pre, path='auto', label='over-cup', **kw), pose=(p, yaw)))
        out.append(dict(go(robo, arm, target, label='lower-into-cup', **kw), pose=(p, yaw)))
        tcp = np.asarray(robo.state().arm(arm).tcp_pos, float)
        if float(np.linalg.norm(tcp[:2] - np.array(target[:2]))) <= 0.008 and float(tcp[2] - cup[2]) <= 0.095 + 0.015:
            best = (p, yaw, tcp)
    if best is None:
        return done(False, 'no hand pose reached the release point over the cup (the egg is still held)', holding=bool(float(robo.state().arm(arm).gripper) > 0.2))
    p, yaw, tcp = best
    o = open_hand(robo, arm, 0.72, calls=2)
    out.append(dict(label='release', opening=round(o['opening'], 3), opened=o['opened'], actions=o['actions'], grasp_point_above_carton=round(float(tcp[2] - cup[2]), 3)))
    out.append(go(robo, arm, [tcp[0], tcp[1], 0.915], pitch=p, yaw=yaw, roll=0.0, label='withdraw'))
    return done(True, cup=index, yaw=yaw, pitch=p, inserted=bool(float(tcp[2] - cup[2]) <= 0.082 + 0.008))



def carton_look(robo, arm, H):
    """The four cups from the wrist camera looking straight down: which hold an egg, and whether it stands or leans."""
    start = used(robo)
    name = 'cam_%s_wrist' % arm
    centre = np.asarray(H['centre'], float)
    plane = centre[2] + 0.046
    rec = None
    for dz in (0.208, 0.173, 0.138):
        z = plane + dz
        ahead = 0.0155 + (240.0 - 130.0) / 397.0 * (dz + 0.077)
        rec = go(robo, arm, [centre[0], centre[1] - ahead, z], pitch=60.0, yaw=0.0, roll=0.0, path='auto', gripper=robo.CLOSE, label='carton-look')
        if rec['reached'] or not rec.get('ik_error'):
            break
    if not near_enough(rec):
        return dict(ok=False, reason='look pose over the carton not reached', reply=rec, actions=used(robo) - start, cups=None, camera=name)
    found = find_eggs(robo, name, region=(centre, 0.10), z=plane)
    cups, taken = [], set()
    for cup in H['cups']:
        best = None
        for j, e in enumerate(found['eggs']):
            dist = float(np.linalg.norm(e['centre'][:2] - np.asarray(cup)[:2]))
            if dist <= 0.018 and j not in taken and (best is None or dist < best[0]):
                best = (dist, j)
        if best is None:
            cups.append(dict(present=False, leaning=None))
        else:
            e = found['eggs'][best[1]]
            taken.add(best[1])
            cups.append(dict(present=True, leaning=bool(e['length'] > 0.050), lying=bool(e['length'] > 0.055), length=round(e['length'], 4),
                             heading_deg=e['heading_deg'], centre=e['centre'], offset=round(best[0], 4)))
    strays = [e for j, e in enumerate(found['eggs']) if j not in taken]
    return dict(ok=True, reason=None, cups=cups, strays=strays, eggs=found['eggs'], camera=name, reply=rec, actions=used(robo) - start)


def straighten(robo, arm, H, index, cup):
    """Stand a leaning egg up in its cup: the closed fingertips reach over its upper end and pull it back toward the cup.

    An egg released too tilted comes to rest across its cup, lower end against the cup wall and upper end on the
    rim on the far side from the robot. A short pull of the upper end toward the robot lets it drop into the cup.
    """
    start = used(robo)
    out = []
    cz = float(H['centre'][2])
    egg = np.asarray(cup['centre'], float)[:2]
    h = math.radians(cup['heading_deg'])
    d = np.array([math.cos(h), math.sin(h)])
    if d[1] < 0:
        d = -d
    slack = float(np.dot(egg - np.asarray(H['cups'][index], float)[:2], d))
    if slack < -0.006:
        d = -d
    yaw = (math.degrees(math.atan2(d[1], d[0])) - 90.0 + 180.0) % 360.0 - 180.0
    s60, c60 = math.sin(math.radians(60.0)), math.cos(math.radians(60.0))
    tip = np.array([egg[0] + d[0] * 0.035, egg[1] + d[1] * 0.035, cz + 0.060])
    tcp = tip + 0.022 * np.array([-d[0] * c60, -d[1] * c60, s60])
    kw = dict(pitch=60.0, yaw=yaw, roll=0.0, gripper=robo.CLOSE)
    out.append(go(robo, arm, [tcp[0], tcp[1], tcp[2] + 0.06], path='auto', label='above-upper-end', **kw))
    if not out[-1]['reached']:
        return dict(ok=False, reason='pose above the leaning egg not reached', replies=out, actions=used(robo) - start)
    out.append(go(robo, arm, tcp, label='down-behind-upper-end', **kw))
    out.append(go(robo, arm, [tcp[0] - 0.030 * d[0], tcp[1] - 0.030 * d[1], tcp[2]], label='pull-upright', **kw))
    out.append(go(robo, arm, [tcp[0] - 0.030 * d[0], tcp[1] - 0.030 * d[1], tcp[2] + 0.06], label='up', **kw))
    return dict(ok=True, reason=None, replies=out, actions=used(robo) - start)


def push_in(robo, arm, H, index, cup):
    """An egg lying flat across its cup rests on the rim at both ends: push its near end along its length until that end drops in.

    The closed fingertips come down just in front of the end nearer the robot and push 1.6 cm along the egg. The
    egg is left leaning, upper end away from the robot, which is what ``straighten`` corrects.
    """
    start = used(robo)
    out = []
    cz = float(H['centre'][2])
    egg = np.asarray(cup['centre'], float)[:2]
    h = math.radians(cup['heading_deg'])
    d = np.array([math.cos(h), math.sin(h)])
    if d[1] < 0:
        d = -d
    yaw = (math.degrees(math.atan2(d[1], d[0])) - 90.0 + 180.0) % 360.0 - 180.0
    s60, c60 = math.sin(math.radians(60.0)), math.cos(math.radians(60.0))
    tip = np.array([egg[0] - d[0] * (EGG_LENGTH_M / 2.0 + 0.014), egg[1] - d[1] * (EGG_LENGTH_M / 2.0 + 0.014), cz + 0.052])
    tcp = tip + 0.022 * np.array([-d[0] * c60, -d[1] * c60, s60])
    kw = dict(pitch=60.0, yaw=yaw, roll=0.0, gripper=robo.CLOSE)
    out.append(go(robo, arm, [tcp[0], tcp[1], tcp[2] + 0.06], path='auto', label='above-near-end', **kw))
    if not out[-1]['reached']:
        return dict(ok=False, reason='pose in front of the lying egg not reached', replies=out, actions=used(robo) - start)
    out.append(go(robo, arm, tcp, label='down-before-near-end', **kw))
    out.append(go(robo, arm, [tcp[0] + 0.030 * d[0], tcp[1] + 0.030 * d[1], tcp[2]], label='push-along-egg', **kw))
    out.append(go(robo, arm, [tcp[0] + 0.030 * d[0], tcp[1] + 0.030 * d[1], tcp[2] + 0.06], label='up', **kw))
    return dict(ok=True, reason=None, replies=out, actions=used(robo) - start)


def cups_overlay(robo, H, look):
    """Evidence image: the wrist view of the carton with each cup marked (green = egg standing, red = leaning, yellow = empty)."""
    K, E = cam(robo, look['camera'])
    im = Image.fromarray(rgb_of(robo, look['camera'])).convert('RGB')
    dr = ImageDraw.Draw(im)
    for i, cup in enumerate(H['cups']):
        info = look['cups'][i]
        r, c = project(K, E, np.asarray(cup) + [0.0, 0.0, 0.046])[0]
        col = (255, 255, 0) if not info['present'] else ((255, 0, 0) if info['leaning'] else (0, 255, 0))
        dr.ellipse([c - 30, r - 30, c + 30, r + 30], outline=col, width=3)
        dr.text((c - 4, r - 44), str(i), fill=col)
    return im


def close_lid(robo, arm, H):
    """Push the standing lid over from behind; its hinge is free, so it falls shut once past upright.

    The push point is tried a little toward the pushing arm's own side of the lid first (shorter reach), then at
    the lid's middle. Nothing moves when the pose behind the lid is out of this arm's reach.
    """
    start = used(robo)
    out = []

    def done(ok, reason=None, **kw):
        return dict(ok=ok, reason=reason, replies=out, actions=used(robo) - start, **kw)

    cx, cy, cz = [float(v) for v in H['centre']]
    hinge_y = cy + CARTON_HINGE_Y_M
    top_z = cz + CARTON_HINGE_Z_M + CARTON_LID_LENGTH_M
    kw = dict(pitch=60.0, yaw=0.0, roll=0.0, gripper=robo.CLOSE)
    behind = hinge_y + 0.040 + 0.040
    own = -1.0 if arm == 'left' else 1.0
    x = None
    for shift in (0.030, 0.0):
        x = cx + own * shift
        out.append(dict(go(robo, arm, [x, behind, top_z + 0.06], path='auto', label='above-lid', **kw), arm=arm))
        if out[-1]['reached']:
            break
    if not out[-1]['reached']:
        return done(False, 'pose behind the lid not reached by the %s arm' % arm)
    out.append(go(robo, arm, [x, behind, top_z - 0.030], label='behind-lid', **kw))
    out.append(glide(robo, arm, [x, hinge_y - 0.010, top_z - 0.030], step_m=0.018, label='lid-push', **kw))
    out.append(go(robo, arm, [x, hinge_y - 0.010, top_z + 0.06], label='lid-clear', **kw))
    return done(True)


def finish(robo):
    """Open both hands and return both arms to the start pose. The episode may end by itself during this."""
    start = used(robo)
    out = []
    ended = False
    try:
        for arm in ('left', 'right'):
            if robo.state().arm(arm).gripper < 0.95:
                o = open_hand(robo, arm, 1.0, calls=1)
                out.append(dict(label='open-' + arm, opening=round(o['opening'], 3), actions=o['actions']))
        for _ in range(3):
            h = robo.home('both')
            out.append(dict(label='home', reached=bool(h.reached), error=round(float(h.max_joint_error_rad), 4), actions=h.steps_used))
            if h.reached:
                break
    except Exception as exc:
        ended = True
        out.append(dict(label='home', episode_ended=True, message=str(exc)[:120]))
    try:
        spent = used(robo) - start
    except Exception:
        spent = None
    return dict(ok=bool(ended or (out and out[-1].get('reached'))), episode_ended=ended, replies=out, actions=spent)


class EggRoutines:
    """Runs the egg task's executed routines and reports what each one measured.

    ``survey()`` looks (no motion). ``fill()`` moves eggs from the basket into
    empty cups one at a time, checking each from straight above with the wrist
    camera, until four cups hold a standing egg or a step fails; ``move_one()``
    does a single egg. ``check_cups()`` looks into the carton again and stands
    up any egg that leans. ``close_lid()`` pushes the lid shut and checks it.
    ``finish()`` opens the hands and homes both arms. Every call returns a dict
    with ``ok``, ``reason``, ``measured`` and ``images``; ``show(out, display)``
    displays them. A call that reports ok False has stopped at a safe point;
    calling it again measures the scene again.
    """

    def __init__(self, robo):
        self.robo = robo
        self.H = None
        self.arm = None
        self.basket = None
        self.look_pose = None
        self.cups = None
        self.fixes = {}
        self.log = []

    @staticmethod
    def show(out, display):
        for im in out.get('images') or ():
            display(im)
        print({k: out.get(k) for k in ('step', 'ok', 'reason', 'measured', 'episode_actions')})

    def _out(self, step, ok, reason, measured, images, **extra):
        out = dict(step=step, ok=bool(ok), reason=reason, measured=measured, images=images, episode_actions=used(self.robo), **extra)
        self.log.append(dict(step=step, ok=out['ok'], reason=reason, measured=measured, episode_actions=out['episode_actions']))
        return out

    def _park(self):
        """Take an arm that is over the middle of the table (in the head camera's way) to its own side, above everything."""
        moved = False
        for arm, side in (('left', -1.0), ('right', 1.0)):
            st = self.robo.state().arm(arm)
            x, y, z = [float(v) for v in st.tcp_pos]
            if abs(x) < 0.17 and y > -0.33:
                if z < 0.915 + 0.04:
                    go(self.robo, arm, [x, y - 0.03, 0.915 + 0.06], gripper=self.robo.KEEP, label='raise')
                go(self.robo, arm, [side * 0.30, -0.24, 0.98], pitch=60.0, yaw=0.0, roll=0.0, path='auto', gripper=self.robo.KEEP, label='park')
                moved = True
        return moved

    def _measure(self):
        H = carton_pose(self.robo)
        if not H.get('ok') and self.H is None and self._park():
            H = carton_pose(self.robo)
        if H.get('ok'):
            if self.H is not None and np.linalg.norm(np.asarray(H['centre']) - np.asarray(self.H['centre'])) < 0.015:
                H = dict(H, centre=self.H['centre'], cups=self.H['cups'])
            self.H = H
        B = find_basket(self.robo)
        if B.get('ok'):
            if self.basket is not None and np.linalg.norm(np.asarray(B['centre']) - np.asarray(self.basket['centre'])) < 0.03:
                B = dict(B, centre=self.basket['centre'])
            self.basket = B
            if self.H is not None and self.arm is None:
                self.arm = 'left' if B['centre'][0] < self.H['centre'][0] else 'right'
        states = cup_states(self.robo, self.H) if self.H is not None else None
        return H, B, states

    def survey(self):
        """Measure the carton, its cups and the basket from the head view. No motion (an arm hiding the carton is first moved aside)."""
        H, B, states = self._measure()
        seen = find_eggs(self.robo, 'cam_head', region=(B['centre'], BASKET_SEARCH_RADIUS_M + 0.03)) if B.get('ok') else dict(count=0, eggs=[])
        measured = dict(carton_found=bool(H.get('ok')), basket_found=bool(B.get('ok')), arm=self.arm,
                        cups_occupied=None if states is None else [s['occupied'] for s in states],
                        cups_standing=None if states is None else [s.get('standing') for s in states],
                        lid=H.get('lid'), eggs_seen_in_basket=seen['count'],
                        carton_centre=None if self.H is None else np.round(self.H['centre'], 3).tolist(),
                        basket_centre=None if self.basket is None else np.round(self.basket['centre'], 3).tolist())
        ok = bool(self.H is not None and self.basket is not None)
        if self.cups is None and states is not None and H.get('ok'):
            self.cups = [dict(present=bool(s['occupied']), leaning=(None if s.get('standing') is None else not s['standing'])) for s in states]
        images = [carton_overlay(self.robo, self.H or {}, states)]
        return self._out('survey', ok, None if ok else (H.get('reason') or B.get('reason')), measured, images)

    def _ready(self, step):
        if self.H is None or self.arm is None or self.basket is None:
            s = self.survey()
            if not s['ok'] or self.arm is None:
                return self._out(step, False, 'carton or basket not measured: ' + str(s['reason']), s['measured'], s['images'])
        return None

    def _cup_summary(self):
        return dict(cups_hold_egg=[c['present'] for c in self.cups], cups_leaning=[c.get('leaning') for c in self.cups])

    def check_cups(self, fix=True):
        """Look straight down into the carton with the wrist camera; stand up any egg that leans (``fix``). ok when four eggs stand in their cups."""
        robo = self.robo
        bad = self._ready('check_cups')
        if bad:
            return bad
        rows = []
        look = carton_look(robo, self.arm, self.H)
        rows.append(dict(look['reply'], count=None if look['cups'] is None else sum(c['present'] for c in look['cups'])))
        if not look['ok']:
            self._park()
            states = cup_states(robo, self.H)
            self.cups = [dict(present=bool(st['occupied']), leaning=(False if st.get('standing') is None else not st['standing'])) for st in states]
            ok = all(c['present'] and not c['leaning'] for c in self.cups)
            return self._out('check_cups', ok, None if ok else 'not every cup holds a standing egg (head camera; the wrist camera could not reach over the carton)',
                             dict(self._cup_summary(), seen_by='head camera'), [carton_overlay(robo, self.H, states)], replies=rows)
        for _ in range(3):
            leaning = [i for i, c in enumerate(look['cups']) if c['present'] and c['leaning'] and self.fixes.get(i, 0) < 2]
            if not fix or not leaning:
                break
            i = leaning[0]
            self.fixes[i] = self.fixes.get(i, 0) + 1
            if look['cups'][i].get('lying'):
                st = push_in(robo, self.arm, self.H, i, look['cups'][i])
            else:
                st = straighten(robo, self.arm, self.H, i, look['cups'][i])
            rows += [dict(r, cup=i) for r in st['replies']]
            look = carton_look(robo, self.arm, self.H)
            rows.append(dict(look['reply'], count=None if look['cups'] is None else sum(c['present'] for c in look['cups'])))
            if not look['ok']:
                return self._out('check_cups', False, look['reason'], None, [])
        self.cups = look['cups']
        measured = dict(self._cup_summary(), cups_seen_length_cm=[None if not c['present'] else round(100.0 * c['length'], 1) for c in self.cups],
                        eggs_elsewhere_on_carton=len(look['strays']), corrections_tried=dict(self.fixes))
        ok = all(c['present'] and not c['leaning'] for c in self.cups)
        reason = None if ok else ('an egg leans in its cup' if all(c['present'] for c in self.cups) else 'not every cup holds an egg')
        return self._out('check_cups', ok, reason, measured, [cups_overlay(robo, self.H, look)], replies=rows)

    def move_one(self):
        """Take one egg from the basket to the first empty cup (back row first), then check the cup from above and stand the egg up if it leans."""
        robo = self.robo
        bad = self._ready('move_one')
        if bad:
            return bad
        arm = self.arm
        rows = []
        if self.cups is None:
            c = self.check_cups(fix=False)
            if self.cups is None:
                return self._out('move_one', False, c['reason'], c['measured'], c['images'])
        order = (1, 0, 3, 2) if arm == 'left' else (0, 1, 2, 3)
        empty = [i for i in order if not self.cups[i]['present']]
        if not empty:
            return self._out('move_one', True, 'all four cups already hold an egg', self._cup_summary(), [])
        index = empty[0]
        picked = None
        evidence = []
        eggs = []
        if 0.2 < float(robo.state().arm(arm).gripper) < 0.5 and float(robo.state().arm(arm).tcp_pos[2]) > 0.865:
            picked = dict(ok=True, replies=[], width=None, carried_over=True)
            rows.append(dict(label='egg-already-held', gripper=round(float(robo.state().arm(arm).gripper), 3)))
        else:
            look = basket_look(robo, arm, self.basket['centre'])
            rows.append(dict(label='basket-look', ok=look['ok'], count=look['count'], actions=look['actions'], reason=look.get('reason')))
            if look.get('reply') and near_enough(look['reply']):
                self.look_pose = [float(v) for v in robo.state().arm(arm).tcp_pos]
            if not look['ok']:
                return self._out('move_one', False, look['reason'], dict(self._cup_summary(), eggs_in_basket=0), [Image.fromarray(rgb_of(robo, 'cam_%s_wrist' % arm))])
            eggs = look['eggs']
            evidence = [eggs_overlay(robo, look['camera'], eggs)]
        nudges = 0
        attempts = 4 if picked is None else 0
        for attempt in range(attempts):
            order = pick_order(eggs, self.basket['centre'])
            choice = order[0]
            at_wall = wall_side(eggs[choice], self.basket['centre']) > 0.095
            after_misses = picked is not None and attempt == 2
            if (at_wall or after_misses) and nudges < 2 and attempt < attempts - 1:
                nudges += 1
                n = nudge_in(robo, arm, eggs[choice], self.basket['centre'])
                rows += [dict(r, egg=choice) for r in n['replies']]
            else:
                picked = pick_egg(robo, arm, eggs[choice], self.basket['centre'])
                rows += [dict(r, egg=choice) for r in picked['replies']]
                if picked['ok']:
                    break
            if attempt == attempts - 1:
                break
            relook = basket_look(robo, arm, self.basket['centre'])
            rows.append(dict(label='basket-look', ok=relook['ok'], count=relook['count'], actions=relook['actions']))
            if relook.get('reply') and near_enough(relook['reply']):
                self.look_pose = [float(v) for v in robo.state().arm(arm).tcp_pos]
            if not relook['ok']:
                break
            eggs = relook['eggs']
            evidence = [eggs_overlay(robo, relook['camera'], eggs)]
        if picked is None or not picked['ok']:
            return self._out('move_one', False, 'pick: ' + str(picked['reason'] if picked else 'no egg chosen'),
                             dict(self._cup_summary(), eggs_in_basket=len(eggs)), evidence)
        placed = place_egg(robo, arm, self.H, index, self.basket['centre'])
        rows += placed['replies']
        if not placed['ok']:
            return self._out('move_one', False, 'place: ' + str(placed['reason']), dict(self._cup_summary(), cup=index), evidence, replies=rows)
        if len(empty) == 1:
            check = self.check_cups(fix=True)
            rows += check.get('replies') or []
            if self.cups is None:
                return self._out('move_one', False, check['reason'], dict(cup=index), evidence, replies=rows)
            images = evidence + check['images']
        else:
            rows.append(go(robo, arm, self.look_pose or [self.basket['centre'][0], self.basket['centre'][1] - 0.1, 1.01],
                           pitch=60.0, yaw=0.0, roll=0.0, path='auto', gripper=robo.CLOSE, label='back-over-basket'))
            states = cup_states(robo, self.H)
            self.cups[index] = dict(present=bool(states[index]['occupied']), leaning=(None if states[index].get('standing') is None else not states[index]['standing']))
            images = evidence + [carton_overlay(robo, self.H, states)]
        info = self.cups[index]
        ok = bool(info['present'] and not info['leaning'])
        measured = dict(self._cup_summary(), cup=index, cup_holds_egg=bool(info['present']), egg_leaning=info.get('leaning'), pinch_width=picked.get('width'),
                        release_height=placed['replies'][-2].get('grasp_point_above_carton'), hand_pitch=placed.get('pitch'))
        reason = None if ok else ('cup %d does not hold the egg after release' % index if not info['present'] else 'the egg in cup %d leans' % index)
        return self._out('move_one', ok, reason, measured, images, replies=rows)

    def fill(self, limit=4):
        """Move eggs one at a time until all four cups hold a standing egg, a step fails, or ``limit`` eggs were moved."""
        bad = self._ready('fill')
        if bad:
            return dict(bad, step='fill')
        last = None
        moved = 0
        for _ in range(limit):
            if self.cups is not None and all(c['present'] for c in self.cups):
                break
            last = self.move_one()
            if not last['ok'] and not (last.get('measured') or {}).get('cup_holds_egg'):
                return dict(last, step='fill', eggs_moved=moved)
            moved += 1
        if last is None or last.get('step') != 'move_one' or any(c.get('leaning') is not False for c in self.cups) or not last['ok']:
            last = self.check_cups(fix=True)
        ok = self.cups is not None and all(c['present'] and not c['leaning'] for c in self.cups)
        return self._out('fill', ok, None if ok else 'not all four cups hold a standing egg yet', dict(self._cup_summary(), eggs_moved=moved), last.get('images') or [])

    def close_lid(self):
        """Push the open lid shut with the working arm, then look down at the carton: a closed lid hides every egg."""
        robo = self.robo
        bad = self._ready('close_lid')
        if bad:
            return bad
        rows = []
        r = None
        first = 'left' if float(self.H['centre'][0]) < 0.0 else 'right'
        lid_arm = first
        for lid_arm in (first, 'right' if first == 'left' else 'left'):
            if lid_arm != self.arm:
                side = -1.0 if self.arm == 'left' else 1.0
                tcp = [float(v) for v in robo.state().arm(self.arm).tcp_pos]
                if abs(tcp[0] - float(self.H['centre'][0])) < 0.15:
                    rows.append(go(robo, self.arm, [float(self.H['centre'][0]) + side * 0.20, float(self.H['centre'][1]) - 0.12, max(tcp[2], 0.915 + 0.08)],
                                   path='auto', gripper=robo.CLOSE, label='step-aside'))
            r = close_lid(robo, lid_arm, self.H)
            rows += list(r['replies'])
            if r['ok']:
                break
        if not r['ok']:
            return self._out('close_lid', False, r['reason'], dict(lid_closed=False, pushed=False), [], replies=rows)
        look = carton_look(robo, lid_arm, self.H)
        rows.append(look['reply'])
        seen = None if look['cups'] is None else sum(c['present'] for c in look['cups']) + len(look['strays'])
        closed = bool(look['ok'] and seen == 0)
        images = [Image.fromarray(rgb_of(robo, look['camera']))] if look['ok'] else []
        if not look['ok']:
            self._park()
            H1 = carton_pose(robo)
            closed = bool(H1.get('ok') and H1.get('lid') == 'closed')
            images = [carton_overlay(robo, self.H)]
        ok = bool(r['ok'] and closed)
        return self._out('close_lid', ok, None if ok else (r.get('reason') or look.get('reason') or 'eggs still visible from above: the lid is not shut'),
                         dict(lid_closed=closed, eggs_visible_from_above=seen, pushed=bool(r['ok']), pushed_by=lid_arm), images, replies=rows)

    def status(self):
        """Look again from the head camera: cups, lid, eggs still seen in the basket (an arm in the way is moved aside)."""
        self._park()
        return dict(self.survey(), step='status')

    def finish(self):
        """Open both hands and return both arms to the start pose; the episode ends by itself then if the whole task is done."""
        f = finish(self.robo)
        return dict(step='finish', ok=bool(f['ok']), episode_ended=bool(f.get('episode_ended')), replies=f['replies'])


_ROUTINES = {}


def routines(robo):
    """The EggRoutines object for this episode (created once, kept between cells)."""
    if 'r' not in _ROUTINES:
        _ROUTINES['r'] = EggRoutines(robo)
    return _ROUTINES['r']
